/* Name: Buterflyse, Class: CMIS 125, Prof: REDACTED, Date: 10/16/2026, Description: This program takes an integer input from the user and determines weather that integer is within the range of specified seasons, if so the script will return a message that estimates the season. If the temperature is too high or low, it will return an error message.*/ import java.util.Scanner; public class ProbableSeason { public static void main(String[] args){Scanner scan = new Scanner(System.in)/*Creating scanner item.*/; System.out.println("Please enter the current temperature: "); int temp = scan.nextInt();/*Get input int from user.*/ String output=""; /*Following if statement checks the input and depending on what it is will return what season it might be.*/if(temp > 110 || temp < -5){System.out.println("ERR: Temperature entered is outside of the allowed range."); System.exit(0);}else if(temp >= 90){output="Summer";}else if(temp < 90 && temp >= 70){output = "Spring";}else if(temp < 70 && temp >= 50){output = "Fall";}else{ output = "Winter";} System.out.println("According to the provided temperature, it is likely currently " + output + "."); /*Takes output from if statement and prints out the likely season to user.*/}}